#!/usr/bin/env python3
"""Add categories 3-6 to the multilingual benchmark (80 cases)."""
import os, json
from typing import List, Dict, Any

BENCH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "multilingual_clinical_200_benchmark.json")

with open(BENCH, encoding="utf-8") as f:
    data = json.load(f)
cases = data["cases"]
start = len(cases)

def add(cat, lang, q, ref, facts, sources, safety=False, diff="intermediate"):
    idx = len(cases) + 1
    cases.append({
        "id": f"vastcare_bench_{idx:03d}",
        "category": cat, "language": lang, "question": q,
        "reference_answer": ref, "key_medical_facts": facts,
        "evidence_sources": sources, "safety_critical": safety,
        "difficulty": diff, "expert_reviewed": False,
        "annotation_label": "Guideline-Derived Clinical Evaluation Benchmark"
    })

# ============ CATEGORY 3: TELUGU-ENGLISH MIXED / CODE-SWITCHED (20) ============
add("telugu_english_mixed","te-en","Doctor sugar levels control lo levu ante next step enti?","Blood sugar control lo lekapothe, HbA1c test cheyinchali. 3 months average glucose telustundi. Diet lo refined carbs tagginchaali, regular walking start cheyaali. Doctor prescribe chesina metformin or other OHA medications time ki teesukovali. Self-monitoring with glucometer important.",["HbA1c reflects 3-month glucose average","Lifestyle modifications are first-line","Medication adherence is critical"],["ADA Standards of Care","RSSDI Guidelines"],False,"basic")
add("telugu_english_mixed","te-en","BP tablets daily teesukuntunna but side effects vasthunnaayi - headache, dizziness. Stop cheyyacha?","BP medications sudden ga stop cheyyakudadu - rebound hypertension vachchi stroke or heart attack risk peragutundi. Side effects doctor ki report cheyaali. Doctor alternative medication ki switch chestaru - ACE inhibitors, ARBs, calcium channel blockers lo different options untaayi. Never self-discontinue antihypertensives.",["Never stop BP medications abruptly","Rebound hypertension can cause stroke","Doctor can switch to alternative medications"],["ACC/AHA Hypertension Guidelines","IHCI Protocol"],True,"intermediate")
add("telugu_english_mixed","te-en","Baby ki 6 months ayyindi, weaning foods start cheyyali - emi ivvaali first?","6 months complete ayina tarvata complementary feeding start cheyyali. First foods ga well-cooked mashed rice with dal, ragi porridge, mashed banana, or suji kheer ivvaali. One new food at a time introduce cheyaali - 3 days gap tho allergic reactions observe cheyaali. Salt, sugar, honey avoid cheyaali first year lo.",["Start complementary foods at completed 6 months","Introduce one new food every 3 days to watch for allergies","Avoid salt, sugar, and honey in first year"],["WHO Complementary Feeding Guidelines","IAP Infant Nutrition"],False,"basic")
add("telugu_english_mixed","te-en","Thyroid problem unte pregnancy lo risk emiti? Tablets continue cheyyala?","Hypothyroidism in pregnancy lo untreated vadalthe miscarriage, preterm delivery, low birth weight, maru intellectual disability risk untundi baby ki. Levothyroxine tablets pregnancy lo continue cheyyalsinde - dosage increase avvalsina avasaram untundi. Every 4-6 weeks TSH monitor cheyyali. Endocrinologist tho regular follow-up mandatory.",["Untreated hypothyroidism risks miscarriage and preterm birth","Levothyroxine must continue and dose often increases in pregnancy","TSH monitoring every 4-6 weeks required"],["ATA Guidelines for Thyroid Disease in Pregnancy","Endocrine Society"],True,"intermediate")
add("telugu_english_mixed","te-en","Dengue confirm ayyindi - platelet count 80000. Hospital lo admit avvala?","Platelet count 80,000 unte immediate hospitalization avasaram ledu kani close monitoring mandatory. Warning signs - severe abdominal pain, persistent vomiting, bleeding gums/nose, blood in vomit or stools, extreme fatigue, breathlessness - ivi emannaa vaste immediate admission avasaram. Daily CBC tho platelet trend monitor cheyyali. Hydration maintain cheyyali.",["Platelet 80,000 needs close monitoring but not necessarily admission","Warning signs require immediate hospitalization","Daily CBC and adequate hydration essential"],["WHO Dengue Guidelines","NVBDCP Protocol"],True,"intermediate")
add("telugu_english_mixed","te-en","Periods irregular ga vastunnaayi - PCOD test cheyyinchukovala?","Irregular periods ki multiple causes untaayi - PCOD most common among them. Doctor ultrasound pelvis, hormonal profile (LH, FSH, testosterone, thyroid), fasting insulin, mru fasting glucose tests suggest chestaru. PCOD diagnosis ki Rotterdam criteria use chestaru - oligomenorrhea, clinical/biochemical hyperandrogenism, polycystic ovarian morphology lo 2 out of 3 unte confirm.",["PCOD is common cause but not the only cause of irregular periods","Rotterdam criteria requires 2 of 3 features for diagnosis","Hormonal profile and ultrasound are key investigations"],["ESHRE/ASRM Rotterdam Consensus","FOGSI PCOS Guidelines"],False,"intermediate")
add("telugu_english_mixed","te-en","Kidney stones unnaayi, surgery avasarama leka tablets tho dissolve avtaaya?","Stone size and type meedha depend avutundi. 5mm kante chinna stones usually urine dwara naturally pass avutaayi - doctor alpha-blocker (tamsulosin) prescribe chesi water intake penchmaani cheptaru. 10mm paina stones ki ESWL (shock wave therapy) or ureteroscopy avasaram. Uric acid stones matrame medical dissolution ki respond avutaayi. Calcium oxalate stones dissolve kaavu.",["Stones <5mm often pass naturally with hydration and medication","Stones >10mm typically need ESWL or surgical intervention","Only uric acid stones respond to medical dissolution therapy"],["AUA/EAU Urolithiasis Guidelines","USI Clinical Practice"],False,"intermediate")
add("telugu_english_mixed","te-en","Cholesterol high ani report vachindi - statin tablets life long teesukovala?","High-risk patients ki statins usually long-term or lifelong therapy. Cardiovascular risk assessment meedha depend avutundi - 10-year ASCVD risk calculate chestaru. High-intensity statins (atorvastatin 40-80mg) LDL ni 50% paina reduce chestaayi. Diet, exercise, weight loss tho some patients lo medications adjust cheyyachu but doctor consultation lekunda stop cheyyakudadu.",["Statins are typically long-term therapy for high-risk patients","Lifestyle modifications complement but rarely replace statin therapy","Never stop statins without medical consultation"],["ACC/AHA Cholesterol Guidelines","ESC Dyslipidaemia Guidelines"],False,"intermediate")
add("telugu_english_mixed","te-en","CT scan ki radiation exposure ekkuva untundi kadaa - safe na? Eppudu necessary?","CT scan low-dose ionizing radiation use chestundi - single CT abdomen lo approximately 10 mSv radiation untundi. Diagnostic benefit risk ni outweigh chestundi when clinically indicated. Unnecessary repeated scans avoid cheyyali. Pregnant women lo CT avoid cheyali unless life-threatening emergency. Children lo radiation sensitivity ekkuva kabatti MRI or ultrasound alternatives consider cheyyali.",["CT uses ionizing radiation but diagnostic benefit outweighs risk when indicated","Avoid unnecessary repeated scans especially in children","MRI or ultrasound preferred alternatives when possible"],["ACR Appropriateness Criteria","ICRP Radiation Protection Guidelines"],False,"intermediate")
add("telugu_english_mixed","te-en","Antibiotic course complete cheyyakunda middle lo aapesthe enti avtundi?","Antibiotic course incomplete ga aapesthe bacteria completely eliminate kaavu - surviving bacteria resistant strains ga develop avtaayi. Idi antibiotic resistance ki lead avutundi - future lo same antibiotic panicheyyadam aapesthundi. AMR (antimicrobial resistance) global health threat. Doctor prescribe chesina full course complete cheyyali even if symptoms improve.",["Incomplete courses promote antibiotic-resistant bacteria","AMR is a global health threat","Always complete the prescribed full course"],["WHO AMR Global Action Plan","ICMR AMR Guidelines"],True,"intermediate")
add("telugu_english_mixed","te-en","Eye power penchutundi ani phone screen time thagginchamantaaru - idi nijama?","Prolonged near-work and screen time myopia progression ki associated. 20-20-20 rule follow cheyyali - every 20 minutes, 20 feet dooram lo 20 seconds chuudali. Children lo daily 2 hours outdoor activity myopia progression slow chestundi. Blue light glasses ki strong evidence ledu kani screen brightness adjust cheyyali. Regular eye check-ups important.",["Extended screen time is associated with myopia progression","20-20-20 rule helps reduce digital eye strain","Outdoor activity in children helps slow myopia progression"],["American Academy of Ophthalmology Guidelines","AIOS Myopia Consensus"],False,"basic")
add("telugu_english_mixed","te-en","Calcium tablets eppudu teesukovali - morning empty stomach lo na, food tho na?","Calcium carbonate food tho teesukovali - stomach acid digestion ki help avutundi. Calcium citrate empty stomach lo teesukunnaa absorb avtundi. One time lo 500mg kante ekkuva absorb kaadu - split doses lo teesukovali. Iron tablets tho same time lo teesukokudadu - absorption block avutundi. Vitamin D3 calcium absorption ki essential.",["Calcium carbonate needs food for absorption; citrate does not","Maximum 500mg per dose for optimal absorption","Separate from iron supplements; take with Vitamin D"],["NOF Calcium and Vitamin D Guidelines","Endocrine Society"],False,"basic")
add("telugu_english_mixed","te-en","MRI scan ki metal implants unte danger aa? Pacemaker unnollu cheyyinchukogalara?","Traditional MRI strong magnetic field use chestundi - ferromagnetic metal implants move avvachu or heat avvachu, idi dangerous. Conventional pacemakers, cochlear implants, certain aneurysm clips ki MRI contraindicated. MRI-conditional pacemakers ippudu available - specific conditions lo scan cheyyochu. Always inform radiologist about ALL implants before MRI.",["Strong magnetic fields can move or heat ferromagnetic implants","Conventional pacemakers are MRI-contraindicated","MRI-conditional devices exist but need specific protocols"],["ACR Guidance on MR Safe Practices","AHA MRI Safety Statement"],True,"intermediate")
add("telugu_english_mixed","te-en","Diabetes unte wound healing slow avutundi enti? Leg lo wound 2 weeks nunchi heal avvatle.","Diabetes lo high blood glucose microvascular damage chestundi - chinna blood vessels damage ayyi wound ki blood supply taggutundi. White blood cells function impaired avutundi kabatti infection risk peragutundi. Peripheral neuropathy valla pain feel kaadu kabatti wounds notice cheyyaru. 2 weeks heal avvani wound ki doctor consultation mandatory - diabetic foot ulcer progression prevent cheyyali.",["Hyperglycemia impairs microvascular blood supply to wounds","Immune cell function is compromised increasing infection risk","Non-healing wounds >2 weeks need urgent medical evaluation"],["IWGDF Diabetic Foot Guidelines","ADA Diabetic Foot Care"],True,"intermediate")
add("telugu_english_mixed","te-en","Vitamin D deficiency chala common ante - sunlight lo eppudu, entha sepu undali?","India lo Vitamin D deficiency 70-90% prevalence untundi. Morning 10am-2pm madhya direct sunlight exposure face, arms, legs ki 15-20 minutes, week lo 3-4 times sufficient. Dark skin tones ki ekkuva time avasaram. Sunscreen Vitamin D synthesis block chestundi. Severe deficiency (<10 ng/mL) unte oral supplementation 60,000 IU weekly for 8 weeks, then monthly maintenance.",["15-20 minutes midday sun exposure 3-4 times weekly","Dark skin requires longer exposure for adequate synthesis","Severe deficiency needs high-dose oral supplementation"],["Endocrine Society Vitamin D Guidelines","ICMR RDA for Indians"],False,"basic")
add("telugu_english_mixed","te-en","Sleep apnea unte CPAP machine vaadali antaaru - idi lifelong vaadala?","Obstructive Sleep Apnea (OSA) lo CPAP (Continuous Positive Airway Pressure) gold standard treatment. Weight loss achieve chesthe mild-to-moderate OSA resolve avvachu - CPAP discontinue cheyyochu. Severe OSA lo CPAP usually long-term. CPAP alternative ga mandibular advancement devices, positional therapy, or surgical options untaayi. Untreated OSA hypertension, stroke, heart failure risk peragistundi.",["CPAP is gold standard for OSA treatment","Weight loss may resolve mild-moderate OSA","Untreated OSA increases cardiovascular risk significantly"],["AASM Clinical Practice Guidelines for OSA","ATS/ERS Statement"],False,"intermediate")
add("telugu_english_mixed","te-en","Pregnancy lo folic acid tablet eppudu start cheyyali - conceive ayina tarvata chalu kadaa?","Folic acid ideally conception ki 3 months mundu start cheyyali - neural tube development first 28 days lo complete avutundi, appudu chala women ki pregnancy confirm kaadu. Daily 400-800 mcg folic acid supplementation neural tube defects (spina bifida, anencephaly) 70% thaggistundi. Previous NTD history unte 4-5 mg high dose avasaram.",["Start folic acid at least 3 months before conception","400-800 mcg daily prevents 70% of neural tube defects","Higher dose (4-5mg) needed if previous NTD history"],["WHO Folic Acid Supplementation Guidelines","FOGSI Preconception Care"],True,"intermediate")
add("telugu_english_mixed","te-en","Heart attack symptoms lo chest pain kaakunda inkonni signs kuda untaaya? Women lo different ga untaaya?","Heart attack always classic chest pain tho present avvadu. Atypical presentations - jaw pain, left arm pain, upper back pain, severe indigestion, breathlessness, extreme fatigue, cold sweats, nausea. Women lo atypical symptoms more common - unexplained fatigue, shortness of breath, nausea main presentations avvachu without chest pain. Any suspected symptoms ki immediately 108 call cheyyali.",["Heart attacks can present without classic chest pain","Women more frequently have atypical presentations","Immediate emergency response (108) for any suspected symptoms"],["AHA Heart Attack Warning Signs","ESC Acute Coronary Syndrome Guidelines"],True,"intermediate")
add("telugu_english_mixed","te-en","Steroid tablets doctor prescribe chesaaru - sudden ga aapesthe enti avtundi?","Long-term corticosteroid use (2-3 weeks paina) body natural cortisol production suppress chestundi (HPA axis suppression). Sudden discontinuation adrenal crisis ki lead avvachu - symptoms lo severe weakness, low BP, shock, life-threatening collapse. Steroids always gradual tapering schedule tho reduce cheyyali - doctor guided dose reduction over weeks to months.",["Long-term steroids suppress natural cortisol production","Abrupt discontinuation can cause adrenal crisis","Always taper steroids gradually under medical supervision"],["Endocrine Society Adrenal Insufficiency Guidelines","BNF Corticosteroid Withdrawal"],True,"expert")
add("telugu_english_mixed","te-en","Urine infection recurring ga vastundi - prevention kosam emi cheyyali?","Recurrent UTI prevention - adequate hydration daily 2.5-3L, post-voiding hygiene front-to-back wiping, urination after intercourse, tight synthetic undergarments avoid cheyyali. Cranberry products ki limited evidence undi. Post-menopausal women lo vaginal estrogen cream effective. Recurrent UTI (3+ per year) ki low-dose prophylactic antibiotics doctor prescribe cheyyochu.",["Adequate hydration and proper hygiene reduce recurrence","Post-void and post-coital urination recommended","Prophylactic antibiotics for 3+ episodes per year"],["EAU/AUA Recurrent UTI Guidelines","NICE UTI Prevention"],False,"basic")

# ============ CATEGORY 4: MEDICAL TERMINOLOGY (20) ============
add("medical_terminology","te-en","Hypertension ante enti? Telugu lo vivarinchandi.","Hypertension ante rakt'ochch'ha-peedanam (adhika raktapootu). Heart pump chesina rakta pravasam arteries (dhaamanulu) goda meeda chese oppidi nirantaram ekkuvaga undadam. Systolic >= 140 mmHg leda diastolic >= 90 mmHg unte hypertension ga classify chestaru. Idi silent killer - symptoms undavu kani organs damage chestundi.",["Sustained elevated arterial blood pressure","Systolic >=140 or Diastolic >=90 mmHg","Often asymptomatic but damages organs progressively"],["WHO Hypertension Fact Sheet","Harrison's Principles of Internal Medicine"],False,"basic")
add("medical_terminology","te-en","Anemia ante enti? Iron deficiency anemia ki hemolytic anemia ki teda enti?","Anemia ante raktam lo hemoglobin (Hb) level WHO norms kante taggadam (men <13 g/dL, women <12 g/dL). Iron deficiency anemia lo iron supply taggadam valla kotha RBCs sariganirmanam kaavu - microcytic hypochromic. Hemolytic anemia lo RBCs normal ga tayaravutaayi kani premature ga destroy avtaayi - reticulocyte count ekkuvaga untundi, indirect bilirubin peragutundi.",["Anemia = Hb below WHO thresholds","Iron deficiency: impaired RBC production (microcytic)","Hemolytic: premature RBC destruction with elevated reticulocytes"],["WHO Haemoglobin Thresholds","Williams Hematology"],False,"intermediate")
add("medical_terminology","te-en","Antibiotic ante enti? Antiviral tho teda enti? Telugu lo explain cheyyandi.","Antibiotics bacteria (sukshma jeevulu) ni champe leda peragakundu aape oushadhaalu - penicillin, amoxicillin examples. Antivirals viruses (sankramana karakaaalu) ni target chestaayi - oseltamivir (flu), acyclovir (herpes) examples. Antibiotics viral infections like common cold, flu meeda pani cheyyavu. Tappuga vaadalte antibiotic resistance vastundi.",["Antibiotics target bacteria; antivirals target viruses","Antibiotics are ineffective against viral infections","Misuse promotes antibiotic resistance"],["WHO Antimicrobial Resistance Fact Sheet","ICMR AMR Surveillance"],False,"basic")
add("medical_terminology","te-en","ECG (Electrocardiogram) enti? Idi emi cheptundi? Telugu lo ardam cheyyandi.","ECG heart electrical activity ni record chese painless, non-invasive test. Chest, arms, legs meeda electrodes pettu 12-lead recording chestundi. Heart rhythm abnormalities (arrhythmias), heart attack evidence (ST changes), chamber enlargement, electrolyte imbalances detect chestundi. Normal sinus rhythm lo P wave, QRS complex, T wave systematic ga kanipistaayi.",["ECG records cardiac electrical activity non-invasively","Detects arrhythmias, ischemia, and structural changes","Normal pattern shows P wave, QRS complex, and T wave"],["AHA ECG Interpretation Standards","Braunwald's Heart Disease"],False,"basic")
add("medical_terminology","te-en","Biopsy ante enti? Idi cancer confirm chestunda? Telugu lo samjayinchandi.","Biopsy ante body tissue nundi chinna sample surgical ga teesi microscope kinda pathologist examine chesadam. Idi tissue level lo cells normal aa abnormal aa, cancer cells unnaayi aa leeda, cancer type maru grade determine chestundi. Biopsy positive ante cancer confirm. Negative ante cancer ledu kani clinical suspicion unte repeat biopsy avasaram avvachu. Biopsy gold standard for cancer diagnosis.",["Biopsy is tissue sampling for microscopic examination","It is the gold standard for confirming or ruling out cancer","Negative biopsy may need repeat if clinical suspicion persists"],["WHO Classification of Tumours","CAP Cancer Protocols"],False,"intermediate")
add("medical_terminology","te-en","Dialysis ante enti? Idi kidneys badaluga pani chestunda?","Dialysis kidneys fail ayinappudu (ESRD/Stage 5 CKD, eGFR <15) blood lo waste products, excess fluid remove chese artificial process. Hemodialysis lo blood machine dwara filter avutundi (week lo 3 times, 4 hours each). Peritoneal dialysis lo abdomen cavity lo fluid pettidialysis membrane ga peritoneum use avutundi. Dialysis kidney function ni completely replace cheyyadu - transplant definitive treatment.",["Dialysis artificially filters blood when kidneys fail","Hemodialysis uses external machine; peritoneal uses abdominal membrane","Does not fully replace kidney function; transplant is definitive"],["KDIGO Dialysis Guidelines","NKF KDOQI"],False,"intermediate")
add("medical_terminology","te-en","MRI ante enti? CT scan ki MRI ki teda enti?","MRI (Magnetic Resonance Imaging) strong magnetic fields maru radio waves use chesi body soft tissues detailed images create chestundi - radiation ledu. CT scan X-ray radiation use chesi cross-sectional images create chestundi. MRI soft tissues (brain, spinal cord, joints, muscles) ki better. CT bones, lungs, acute bleeding ki faster maru better. MRI scan longer time (30-60 min), CT fast (5-10 min).",["MRI uses magnets and radio waves without ionizing radiation","CT uses X-ray radiation and is faster","MRI superior for soft tissues; CT better for bones and acute imaging"],["ACR Appropriateness Criteria","Radiology Society Guidelines"],False,"basic")
add("medical_terminology","te-en","Insulin resistance ante enti? Idi diabetes ki ela lead avutundi?","Insulin resistance lo body cells (muscle, liver, fat) insulin hormone ki properly respond avvavu - glucose cells loki enter avvadam taggutundi. Pancreas compensate cheyadaniki ekkuva insulin produce chestundi (hyperinsulinemia). Eventually pancreas exhaust ayyi insulin production drop avutundi - blood glucose rise avutundi leading to Type 2 Diabetes. Obesity, sedentary lifestyle, genetics main risk factors.",["Body cells fail to respond properly to insulin signaling","Pancreas compensates with excess insulin production initially","Eventually pancreatic exhaustion leads to Type 2 Diabetes"],["ADA Pathophysiology of Type 2 Diabetes","Endocrine Reviews Insulin Resistance"],False,"intermediate")
add("medical_terminology","te-en","Pneumonia ante enti? Idi common cold ki ela different?","Pneumonia lungs lo alveoli (gali sanchulu) inflammation maru fluid/pus filling - bacteria, viruses, or fungi cause chestaayi. Symptoms: high fever, productive cough with colored sputum, chest pain breathing time, breathlessness. Common cold upper respiratory tract infection matrame - runny nose, sneezing, mild sore throat, low-grade fever. Pneumonia serious, life-threatening avvachu especially elderly maru immunocompromised lo.",["Pneumonia involves alveolar inflammation with fluid/pus","Common cold affects only upper respiratory tract","Pneumonia can be life-threatening in vulnerable populations"],["ATS/IDSA Community-Acquired Pneumonia Guidelines","WHO Pneumonia Fact Sheet"],False,"basic")
add("medical_terminology","te-en","Platelets enti? Low platelet count (thrombocytopenia) valla emi avutundi?","Platelets (thrombocytes) bone marrow lo produce ayye chinna cell fragments - blood clotting lo essential role. Normal count 1.5-4 lakh/mcL. Thrombocytopenia (<1 lakh) lo minor injuries ki prolonged bleeding, petechiae (chinna erra dots skin meeda), purpura (bruises), gum bleeding, heavy menstrual bleeding vastaayi. Severe (<20,000) lo spontaneous internal bleeding or hemorrhagic stroke risk.",["Platelets are essential for blood clotting","Thrombocytopenia causes prolonged bleeding and petechiae","Severe low counts (<20,000) risk spontaneous hemorrhage"],["ASH Thrombocytopenia Guidelines","Harrison's Hematology"],True,"intermediate")
add("medical_terminology","te-en","Metabolism ante enti? Metabolic syndrome ante enti?","Metabolism body lo food ni energy ga convert chese anni chemical reactions total. Metabolic syndrome 5 risk factors lo 3 or more kalisinappudu diagnose chestaru: (1) waist circumference ekkuva (men >90cm, women >80cm Asian criteria), (2) triglycerides >150 mg/dL, (3) HDL taggadam, (4) BP >130/85, (5) fasting glucose >100 mg/dL. Idi heart disease, stroke, diabetes risk significantly peragistundi.",["Metabolism encompasses all body chemical energy conversions","Metabolic syndrome requires 3 of 5 specific risk factors","Significantly increases cardiovascular and diabetes risk"],["IDF Metabolic Syndrome Consensus","AHA/NHLBI Scientific Statement"],False,"intermediate")
add("medical_terminology","te-en","Inflammation ante enti? Acute maru chronic inflammation ki teda enti?","Inflammation body injury or infection ki immune system response. Acute inflammation short-term (days) - redness, swelling, heat, pain, loss of function - healing process part. Chronic inflammation weeks-to-years persistent - autoimmune diseases (rheumatoid arthritis), atherosclerosis, chronic infections lo. Chronic inflammation tissue damage, fibrosis, mru cancer risk ki contribute chestundi.",["Inflammation is the immune system's response to injury/infection","Acute: short-term protective healing response","Chronic: prolonged, can cause tissue damage and disease"],["Robbins Pathologic Basis of Disease","Nature Reviews Immunology"],False,"intermediate")
add("medical_terminology","te-en","Hemoglobin ante enti? HbA1c ki regular Hb ki sambandham enti?","Hemoglobin (Hb) red blood cells lo unde iron-containing protein - oxygen lungs nundi body tissues ki transport chestundi. Normal: men 13-17 g/dL, women 12-16 g/dL. HbA1c glucose molecules hemoglobin ki attach ayina percentage measure - RBC lifespan (120 days) lo average glucose reflect chestundi. Regular Hb anemia diagnose chestundi; HbA1c diabetes monitoring ki use chestundi. Different tests, different purposes.",["Hemoglobin carries oxygen in red blood cells","HbA1c measures glucose attached to hemoglobin over 120 days","Hb diagnoses anemia; HbA1c monitors diabetes control"],["WHO Haemoglobin Standards","ADA HbA1c Position Statement"],False,"basic")
add("medical_terminology","te-en","Autoimmune disease ante enti? Examples ivvandi.","Autoimmune disease lo body immune system tappu ga own healthy cells ni foreign invaders ga gurtinchi attack chestundi. Normally immune system self mru non-self distinguish chestundi - autoimmunity lo ee tolerance break avutundi. Examples: Type 1 Diabetes (pancreas beta cells attack), Rheumatoid Arthritis (joint synovium), Hashimoto's thyroiditis (thyroid gland), Lupus/SLE (multiple organs), Celiac disease (gluten response lo intestine damage).",["Immune system mistakenly attacks body's own healthy cells","Loss of self-tolerance causes the pathology","Examples span organ-specific to systemic diseases"],["NIAMS Autoimmune Disease Overview","Lancet Autoimmunity Review"],False,"intermediate")
add("medical_terminology","te-en","Benign tumor maru malignant tumor ki teda enti?","Benign tumors slow-growing, well-encapsulated, nearby tissues loki invade cheyyavu, metastasize (spread) avvavu - lipoma, fibroma examples. Malignant tumors (cancer) rapidly growing, poorly defined borders, surrounding tissues invade chestaayi, lymph nodes mru distant organs ki metastasize avtaayi. Malignant tumors angiogenesis induce chesi own blood supply create chestaayi. Histological grading mru staging treatment determine chestaayi.",["Benign: slow-growing, encapsulated, non-invasive, no metastasis","Malignant: rapid growth, tissue invasion, metastasis capability","Histological grading and staging guide treatment decisions"],["WHO Classification of Tumours","Robbins Basic Pathology"],False,"intermediate")
add("medical_terminology","te-en","BMI (Body Mass Index) ante enti? Idi accurate health indicator aa?","BMI = weight(kg) / height(m)^2. WHO classification: <18.5 underweight, 18.5-24.9 normal, 25-29.9 overweight, >=30 obese. Asian population ki lower cutoffs: overweight >=23, obese >=25. BMI limitations: muscle mass vs fat distinguish cheyyadu (athletes lo misleading), visceral fat measure cheyyadu, age/gender differences account cheyyadu. Waist circumference mru waist-hip ratio additional important indicators.",["BMI formula: weight in kg divided by height in meters squared","Asian-specific cutoffs are lower than WHO general cutoffs","BMI alone is insufficient; waist circumference adds clinical value"],["WHO BMI Classification","Asian-Pacific BMI Guidelines"],False,"basic")
add("medical_terminology","te-en","Probiotic ante enti? Prebiotic ki teda enti?","Probiotics live beneficial microorganisms (bacteria, yeasts) - gut microbiome health improve chestaayi. Lactobacillus, Bifidobacterium common strains. Fermented foods (curd/yogurt, idli batter, kimchi) lo natural ga untaayi. Prebiotics non-digestible dietary fibers - gut lo existing good bacteria ki food ga serve avutaayi. Inulin, fructooligosaccharides (bananas, onions, garlic lo) common prebiotics. Synbiotics both combine chestaayi.",["Probiotics are live beneficial microorganisms for gut health","Prebiotics are non-digestible fibers that feed good bacteria","Synbiotics combine both probiotics and prebiotics"],["ISAPP Scientific Consensus on Probiotics","WGO Global Guidelines on Probiotics"],False,"basic")
add("medical_terminology","te-en","Stroke ante enti? Ischemic mru hemorrhagic stroke ki teda enti?","Stroke (pakshavaatam) brain ki blood supply suddenly cut ayinaappudu brain cells damage avvadam. Ischemic stroke (87% cases) - blood clot brain artery block chesthe brain tissue ki oxygen, nutrients andavu. Hemorrhagic stroke (13%) - brain lo blood vessel burst ayyi bleeding jarigite surrounding brain tissue ki damage. Both emergencies - FAST recognition (Face drooping, Arm weakness, Speech difficulty, Time to call emergency). Golden hour 4.5 hours for thrombolysis.",["Ischemic stroke: artery blocked by clot (87% of cases)","Hemorrhagic stroke: blood vessel rupture causing brain bleeding","FAST recognition and treatment within 4.5 hours critical"],["AHA/ASA Stroke Guidelines","WHO Stroke Prevention Report"],True,"expert")
add("medical_terminology","te-en","Vaccine ante enti? Live vaccine ki inactivated vaccine ki teda enti?","Vaccine weakened or killed pathogen / pathogen component body ki introduce chesi immune system ni train chese biological preparation. Live attenuated vaccines weakened live organisms use chestaayi (MMR, OPV, BCG) - stronger, longer immunity kani immunocompromised ki risky. Inactivated vaccines killed organisms or subunits use chestaayi (IPV, Hepatitis B, Flu shot) - safer but may need boosters for lasting immunity.",["Vaccines train immune system using weakened/killed pathogens","Live vaccines give stronger immunity but carry risk for immunocompromised","Inactivated vaccines are safer but often need booster doses"],["WHO Position Papers on Vaccines","IAP Guidebook on Immunization"],False,"intermediate")
add("medical_terminology","te-en","Sepsis ante enti? Idi eppudu life-threatening avutundi?","Sepsis body lo infection ki immune system dysregulated response - organ dysfunction ki lead avutundi. Infection site nundi bacteria or toxins bloodstream lo enter ayyi systemic inflammatory response trigger chestaayi. Septic shock lo blood pressure fluids ivvina tarvata kuda dangerously low ga untundi mru organ failure start avutundi. qSOFA criteria: altered mental status, respiratory rate >=22, systolic BP <=100. Mortality 30-40% in septic shock.",["Sepsis is dysregulated immune response to infection causing organ dysfunction","Septic shock involves refractory hypotension despite fluid resuscitation","Mortality reaches 30-40% in septic shock"],["Surviving Sepsis Campaign Guidelines","SSC Bundles and qSOFA Criteria"],True,"expert")

# ============ CATEGORY 5: FACTUAL ACCURACY (20) ============
add("factual_accuracy","en","What is the normal resting heart rate range for adults according to clinical standards?","The normal resting heart rate for adults is 60 to 100 beats per minute (bpm). Well-trained athletes may have physiological resting rates as low as 40-50 bpm (athletic bradycardia) due to enhanced stroke volume and vagal tone. Tachycardia is defined as resting HR >100 bpm, and bradycardia as <60 bpm. Heart rate is influenced by age, fitness, medication, emotional state, and ambient temperature.",["Normal adult resting HR: 60-100 bpm","Athletes may have physiological rates as low as 40-50 bpm","Tachycardia >100 bpm; Bradycardia <60 bpm"],["AHA Heart Rate Guidelines","Braunwald's Heart Disease"],False,"basic")
add("factual_accuracy","en","What is the WHO-defined threshold for diagnosing anemia in adult males versus adult females?","WHO defines anemia as hemoglobin <13.0 g/dL in adult males (>=15 years) and <12.0 g/dL in non-pregnant adult females (>=15 years). For pregnant women, the threshold is <11.0 g/dL. Severity grading: mild (11-12.9 men, 11-11.9 women), moderate (8-10.9 g/dL), severe (<8 g/dL).",["Adult male anemia: Hb <13.0 g/dL","Adult female (non-pregnant) anemia: Hb <12.0 g/dL","Pregnant women anemia: Hb <11.0 g/dL"],["WHO Haemoglobin Concentrations for the Diagnosis of Anaemia","Global Anaemia Estimates WHO"],False,"basic")
add("factual_accuracy","en","What is the fasting blood glucose threshold for diagnosing diabetes mellitus according to ADA criteria?","According to ADA diagnostic criteria: Normal fasting plasma glucose (FPG) is <100 mg/dL. Impaired fasting glucose (prediabetes) is 100-125 mg/dL. Diabetes mellitus is diagnosed at FPG >=126 mg/dL, confirmed on a repeat test. Alternative criteria include 2-hour plasma glucose >=200 mg/dL during OGTT, HbA1c >=6.5%, or random plasma glucose >=200 mg/dL with classic symptoms.",["FPG >=126 mg/dL on two occasions confirms diabetes","Prediabetes: FPG 100-125 mg/dL","Alternative: HbA1c >=6.5% or 2h-OGTT >=200 mg/dL"],["ADA Standards of Medical Care in Diabetes","WHO Diabetes Diagnostic Criteria"],False,"basic")
add("factual_accuracy","en","What are the exact weight-band based dosing categories for NTEP first-line anti-tuberculosis treatment?","NTEP uses fixed-dose combination (FDC) tablets with weight-band dosing: 25-39 kg: 2 FDC tablets; 40-54 kg: 3 FDC tablets; 55-69 kg: 4 FDC tablets; >=70 kg: 5 FDC tablets. Each FDC tablet contains Isoniazid 75mg, Rifampicin 150mg, Pyrazinamide 400mg, Ethambutol 275mg in intensive phase. Continuation phase FDC: Isoniazid 75mg, Rifampicin 150mg, Ethambutol 275mg.",["Weight-band dosing with 2-5 FDC tablets based on patient weight","Each intensive phase FDC: H75, R150, Z400, E275 mg","Continuation phase FDC: H75, R150, E275 mg"],["NTEP Technical and Operational Guidelines 2021","WHO TB Treatment Guidelines"],False,"intermediate")
add("factual_accuracy","te","Normal body temperature range enti maru fever eppudu define chestaru?","Normal body temperature 36.1 C to 37.2 C (97 F to 99 F) oral measurement lo. Fever defined as oral temperature >=38.0 C (100.4 F). Rectal temperature oral kante 0.5 C ekkuva untundi. Axillary (armpit) temperature oral kante 0.5 C taggaga untundi. Hyperpyrexia >=41.5 C (106.7 F) - medical emergency.",["Normal oral temperature: 36.1-37.2 C","Fever defined at >=38.0 C (100.4 F) orally","Hyperpyrexia >=41.5 C is a medical emergency"],["WHO Temperature Standards","Harrison's Principles of Internal Medicine"],False,"basic")
add("factual_accuracy","en","What constitutes the complete lipid profile test and what are the desirable target values?","A complete lipid profile measures: Total Cholesterol (desirable <200 mg/dL), LDL-C (optimal <100 mg/dL, near-optimal 100-129), HDL-C (desirable >=40 mg/dL men, >=50 women), Triglycerides (normal <150 mg/dL), and calculated VLDL. Non-HDL cholesterol (Total cholesterol minus HDL) is an additional secondary target. The test requires 9-12 hour fasting for accurate triglyceride measurement.",["Total Cholesterol desirable <200 mg/dL","LDL optimal <100 mg/dL; HDL desirable >=40/50 mg/dL","Triglycerides normal <150 mg/dL; requires 9-12h fasting"],["NCEP ATP III Guidelines","ACC/AHA Lipid Guidelines"],False,"basic")
add("factual_accuracy","en","What is the normal range for serum creatinine levels and what does an elevated value indicate?","Normal serum creatinine: Males 0.7-1.2 mg/dL, Females 0.5-1.0 mg/dL. Creatinine is a waste product of muscle creatine phosphate metabolism, excreted entirely by kidneys. Elevated creatinine indicates impaired renal filtration (decreased GFR). However, serum creatinine alone is insufficient - eGFR calculated using CKD-EPI equation (incorporating creatinine, age, sex) provides more accurate kidney function assessment.",["Normal: Males 0.7-1.2, Females 0.5-1.0 mg/dL","Elevated creatinine suggests decreased renal filtration","eGFR (CKD-EPI equation) is more accurate than creatinine alone"],["KDIGO CKD Classification","NKF KDOQI Guidelines"],False,"basic")
add("factual_accuracy","en","What is the WHO-recommended schedule for Hepatitis B vaccination in infants?","WHO recommends Hepatitis B birth dose (monovalent) within 24 hours of birth, followed by 2-3 additional doses as part of the primary infant immunization series: typically at 6, 10, and 14 weeks (in pentavalent combination vaccine) under the national immunization schedule. The birth dose prevents perinatal mother-to-child transmission, which carries >90% risk of chronic infection. Anti-HBs >=10 mIU/mL indicates protective immunity.",["Birth dose within 24 hours is critical for PMTCT","Subsequent doses at 6, 10, 14 weeks in pentavalent vaccine","Anti-HBs >=10 mIU/mL confirms protective immunity"],["WHO Position Paper on Hepatitis B Vaccines","NIS India"],False,"intermediate")
add("factual_accuracy","te","Normal blood pressure reading enti mru hypertension stages enti?","Normal BP: Systolic <120 AND Diastolic <80 mmHg. Elevated: Systolic 120-129 AND Diastolic <80. Stage 1 Hypertension: Systolic 130-139 OR Diastolic 80-89. Stage 2 Hypertension: Systolic >=140 OR Diastolic >=90. Hypertensive Crisis: Systolic >180 AND/OR Diastolic >120 - immediate medical attention avasaram.",["Normal: <120/80 mmHg","Stage 1: 130-139/80-89; Stage 2: >=140/>=90 mmHg","Hypertensive crisis: >180/120 requires emergency care"],["ACC/AHA Blood Pressure Classification","JNC 8 Hypertension Guidelines"],False,"basic")
add("factual_accuracy","en","What are the exact caloric and macronutrient requirements per day for an average adult Indian male according to ICMR?","Per ICMR Recommended Dietary Allowances (2020) for a sedentary adult Indian male (reference body weight 65 kg): Energy 2110 kcal/day, Protein 54 g/day (0.83 g/kg), Fat 25-30% of total calories, Carbohydrates 55-60% of total calories, Fiber 40 g/day. For moderate activity: 2710 kcal/day. For heavy activity: 3470 kcal/day.",["Sedentary adult male: 2110 kcal/day, 54g protein","Fat 25-30%, Carbohydrates 55-60% of total calories","Moderate activity: 2710 kcal; Heavy: 3470 kcal/day"],["ICMR-NIN Recommended Dietary Allowances for Indians 2020","ICMR Expert Group Report"],False,"intermediate")
add("factual_accuracy","en","What is the normal range for TSH (Thyroid Stimulating Hormone) and what do abnormal values indicate?","Normal TSH range: 0.4-4.0 mIU/L (some labs use 0.5-5.0). Elevated TSH (>4.0-10.0: subclinical hypothyroidism; >10.0: overt hypothyroidism) indicates underactive thyroid - low T4/T3 production. Suppressed TSH (<0.1 mIU/L) with elevated free T4 indicates hyperthyroidism. TSH is the most sensitive first-line screening test for thyroid dysfunction. Reference ranges may vary by age, pregnancy trimester, and assay.",["Normal TSH: 0.4-4.0 mIU/L","Elevated TSH suggests hypothyroidism; suppressed suggests hyperthyroidism","TSH is the most sensitive first-line thyroid screening test"],["ATA Thyroid Function Testing Guidelines","AACE Thyroid Consensus"],False,"basic")
add("factual_accuracy","en","What is the standard volume and electrolyte composition of normal saline (0.9% NaCl) IV fluid?","Normal Saline (0.9% Sodium Chloride) contains 9 grams NaCl per liter (154 mEq/L Sodium, 154 mEq/L Chloride). Osmolarity is 308 mOsm/L (slightly hyperosmolar compared to plasma 275-295 mOsm/L). pH 5.0 (acidic). It is isotonic and the most commonly used IV resuscitation fluid. Excessive administration can cause hyperchloremic non-anion-gap metabolic acidosis.",["Contains 154 mEq/L each of Na+ and Cl-","Osmolarity 308 mOsm/L, slightly hyperosmolar","Excessive use causes hyperchloremic metabolic acidosis"],["Fluid Therapy Consensus Guidelines","Hartog Critical Care Fluids Review"],False,"intermediate")
add("factual_accuracy","en","What are the CDC-recommended adult vaccination schedules for Tetanus-Diphtheria (Td/Tdap) boosters?","Primary series: if not vaccinated in childhood, 3-dose series (Tdap dose 1, then Td at 4 weeks and 6-12 months). All adults need Td booster every 10 years. One dose of Tdap should replace a Td booster (if not previously received as adult). Pregnant women should receive Tdap during each pregnancy at 27-36 weeks gestation, regardless of prior vaccination, to provide passive antibody protection to the newborn.",["Td booster every 10 years for all adults","One Tdap dose should replace one Td booster in adulthood","Tdap recommended in each pregnancy at 27-36 weeks"],["CDC Adult Immunization Schedule","ACIP Tdap Recommendations"],False,"intermediate")
add("factual_accuracy","en","What is the precise definition and classification of BMI categories with Asian-specific cutoffs?","General WHO BMI: Underweight <18.5, Normal 18.5-24.9, Overweight 25-29.9, Obese Class I 30-34.9, Class II 35-39.9, Class III >=40. Asian-Pacific cutoffs (lower due to higher metabolic risk at lower BMI): Normal 18.5-22.9, Overweight 23-24.9, Obese Class I >=25. Indians have higher visceral adiposity at equivalent BMI compared to Caucasians.",["WHO General: Normal 18.5-24.9, Overweight >=25, Obese >=30","Asian-specific: Overweight >=23, Obese >=25","South Asians have higher metabolic risk at lower BMI levels"],["WHO Expert Consultation on BMI in Asian Populations","ICMR Obesity Guidelines"],False,"basic")
add("factual_accuracy","en","What are the WHO-defined categories for dehydration assessment in children with diarrhea?","WHO classifies dehydration into 3 categories: No Dehydration (Plan A - ORS at home), Some Dehydration (Plan B - ORT under medical supervision: >=2 of sunken eyes, drinks eagerly/thirstily, skin pinch returns slowly), Severe Dehydration (Plan C - IV fluids: >=2 of lethargic/unconscious, sunken eyes, unable to drink, skin pinch returns very slowly >=2 seconds). Severe dehydration is a medical emergency requiring immediate IV Ringer's Lactate.",["Plan A: No dehydration - home ORS","Plan B: Some dehydration - supervised ORT","Plan C: Severe dehydration - emergency IV Ringer's Lactate"],["WHO IMCI Chart Booklet","WHO Diarrhoea Treatment Guidelines"],True,"intermediate")
add("factual_accuracy","en","What is the standard Glasgow Coma Scale (GCS) and how is the total score calculated?","GCS assesses consciousness via 3 components: Eye Opening (E1-4: none=1, to pain=2, to voice=3, spontaneous=4), Verbal Response (V1-5: none=1, incomprehensible=2, inappropriate=3, confused=4, oriented=5), Motor Response (M1-6: none=1, extension=2, flexion=3, withdrawal=4, localizing=5, obeys commands=6). Total GCS = E + V + M, range 3-15. Severe brain injury: GCS 3-8; Moderate: 9-12; Minor: 13-15. GCS 8 or below typically requires intubation.",["Total score range 3-15 from Eye + Verbal + Motor","Severe brain injury: GCS <=8 (intubation threshold)","Components scored independently: E(1-4), V(1-5), M(1-6)"],["Teasdale and Jennett Original GCS Publication","NICE Head Injury Guidelines"],True,"intermediate")
add("factual_accuracy","te","Renal function tests lo normal GFR value enti mru CKD stages enti?","Normal GFR (Glomerular Filtration Rate): >=90 mL/min/1.73m2. CKD Stages: Stage 1 (GFR >=90 with kidney damage markers), Stage 2 (60-89 mildly decreased), Stage 3a (45-59), Stage 3b (30-44), Stage 4 (15-29 severely decreased), Stage 5 (<15 kidney failure/ESRD). CKD-EPI equation age, sex, serum creatinine use chesi eGFR calculate chestundi.",["Normal GFR >=90 mL/min/1.73m2","CKD Stage 5 (ESRD): GFR <15, requires dialysis or transplant","CKD-EPI equation provides standardized eGFR calculation"],["KDIGO CKD Classification 2012","NKF KDOQI"],False,"intermediate")
add("factual_accuracy","en","What are the precise APGAR score components assessed at 1 and 5 minutes after birth?","APGAR assesses 5 parameters, each scored 0-2: Appearance (skin color: blue/pale=0, body pink/extremities blue=1, completely pink=2), Pulse (absent=0, <100=1, >=100=2), Grimace (reflex irritability: no response=0, grimace=1, cry/active withdrawal=2), Activity (muscle tone: limp=0, some flexion=1, active motion=2), Respiration (absent=0, slow/irregular=1, vigorous cry=2). Total 0-10. Score 7-10 normal; <7 may need intervention.",["5 components: Appearance, Pulse, Grimace, Activity, Respiration","Each scored 0-2 for total range 0-10","Score <7 at 5 minutes indicates need for medical intervention"],["AAP Neonatal Resuscitation Guidelines","Original Apgar Score Publication"],False,"intermediate")
add("factual_accuracy","en","What is the standard therapeutic INR range for patients on warfarin for atrial fibrillation?","For non-valvular atrial fibrillation, the target International Normalized Ratio (INR) is 2.0-3.0. For mechanical prosthetic heart valves, the target is typically 2.5-3.5. INR <2.0 indicates subtherapeutic anticoagulation (thromboembolic risk). INR >4.0 significantly increases hemorrhagic risk. INR monitoring frequency: initially twice weekly, then weekly, then monthly once stable.",["Target INR for atrial fibrillation: 2.0-3.0","Mechanical valves require higher target: 2.5-3.5","INR >4.0 carries significant bleeding risk"],["AHA/ACC Atrial Fibrillation Guidelines","ACCP Antithrombotic Therapy Guidelines"],True,"expert")
add("factual_accuracy","en","What is the normal cerebrospinal fluid (CSF) composition and how does it change in bacterial vs viral meningitis?","Normal CSF: clear and colorless, opening pressure 6-20 cmH2O, WBC 0-5/mcL (lymphocytes), protein 15-45 mg/dL, glucose 40-70 mg/dL (60-70% of serum glucose). Bacterial meningitis: turbid, WBC >1000 (neutrophilic predominance), protein >100 mg/dL, glucose <40 mg/dL (low CSF:serum ratio <0.4), positive Gram stain/culture. Viral meningitis: clear, WBC 10-500 (lymphocytic), mildly elevated protein, normal glucose.",["Normal CSF: clear, WBC 0-5, protein 15-45, glucose 40-70 mg/dL","Bacterial: turbid, neutrophilic WBC >1000, low glucose, high protein","Viral: clear, lymphocytic WBC 10-500, normal glucose"],["IDSA Bacterial Meningitis Guidelines","Harrison's Infectious Diseases"],True,"expert")

